package store

import (
	"context"
	"testing"
	"time"
)

// TestStore_Ledger covers the enrichment_failures ledger joint (S1):
// RecordFailure/ClearFailure/ListFailures against the EXISTING table (no DDL).
// Table-driven across record/list round-trip (field preservation + lossless
// next_eligible_at), PK upsert-update (no duplicate row), idempotent clear, and
// the cooldown-distinguishability assertion the derivation will compare to now.
func TestStore_Ledger(t *testing.T) {
	ctx := context.Background()

	t.Run("record_list_roundtrip", func(t *testing.T) {
		s := openStore(t)
		nextElig := time.Now().UTC().Add(7 * 24 * time.Hour)
		if err := s.RecordFailure(ctx, "itm_1", "tv-parser", "exhausted", "rpc timeout", 3, nextElig); err != nil {
			t.Fatalf("RecordFailure: %v", err)
		}
		rows, err := s.ListFailures(ctx)
		if err != nil {
			t.Fatalf("ListFailures: %v", err)
		}
		if len(rows) != 1 {
			t.Fatalf("ListFailures = %d rows, want 1", len(rows))
		}
		r := rows[0]
		if r.ItemID != "itm_1" || r.PluginID != "tv-parser" || r.Status != "exhausted" ||
			r.Reason != "rpc timeout" || r.Attempts != 3 {
			t.Fatalf("round-trip fields = %+v, want itm_1/tv-parser/exhausted/rpc timeout/3", r)
		}
		if r.FailedAt.IsZero() {
			t.Fatalf("FailedAt not stamped: %+v", r)
		}
		// B5: next_eligible_at round-trips losslessly (RFC3339Nano format/parse).
		if !r.NextEligibleAt.Equal(nextElig) {
			t.Fatalf("NextEligibleAt = %v, want %v (lossless round-trip)", r.NextEligibleAt, nextElig)
		}
	})

	t.Run("upsert_updates_same_pk", func(t *testing.T) {
		s := openStore(t)
		first := time.Now().UTC().Add(7 * 24 * time.Hour)
		later := first.Add(7 * 24 * time.Hour) // doubled cooldown (7d -> 14d)
		if err := s.RecordFailure(ctx, "itm_u", "tv-parser", "exhausted", "first", 3, first); err != nil {
			t.Fatalf("RecordFailure #1: %v", err)
		}
		if err := s.RecordFailure(ctx, "itm_u", "tv-parser", "exhausted", "again", 4, later); err != nil {
			t.Fatalf("RecordFailure #2: %v", err)
		}
		rows, err := s.ListFailures(ctx)
		if err != nil {
			t.Fatalf("ListFailures: %v", err)
		}
		if len(rows) != 1 {
			t.Fatalf("ListFailures = %d rows, want 1 (PK conflict -> UPDATE, no duplicate)", len(rows))
		}
		r := rows[0]
		if r.Attempts != 4 || r.Reason != "again" {
			t.Fatalf("upsert fields = %+v, want attempts=4 reason=again", r)
		}
		if !r.NextEligibleAt.Equal(later) {
			t.Fatalf("NextEligibleAt = %v, want %v (upsert advanced the cooldown)", r.NextEligibleAt, later)
		}
	})

	t.Run("clear_idempotent", func(t *testing.T) {
		s := openStore(t)
		if err := s.RecordFailure(ctx, "itm_x", "tv-parser", "no_data", "empty", 1,
			time.Now().UTC().Add(30*24*time.Hour)); err != nil {
			t.Fatalf("RecordFailure: %v", err)
		}
		if rows, _ := s.ListFailures(ctx); len(rows) != 1 {
			t.Fatalf("pre-clear: %d rows, want 1", len(rows))
		}
		if err := s.ClearFailure(ctx, "itm_x", "tv-parser"); err != nil {
			t.Fatalf("ClearFailure (present row): %v", err)
		}
		if rows, _ := s.ListFailures(ctx); len(rows) != 0 {
			t.Fatalf("post-clear: %d rows, want 0", len(rows))
		}
		// INV-idempotent-clear: an absent row returns nil, not an error.
		if err := s.ClearFailure(ctx, "itm_x", "tv-parser"); err != nil {
			t.Fatalf("ClearFailure (absent row) = %v, want nil (idempotent)", err)
		}
	})

	// The S1 joint data-level assertion: a within-cooldown row is distinguishable
	// from an eligible one by comparing NextEligibleAt to now (the derivation's
	// cooldown-skip reads exactly this value).
	t.Run("cooldown_distinguishable", func(t *testing.T) {
		s := openStore(t)
		now := time.Now().UTC()
		nextElig := now.Add(7 * 24 * time.Hour) // exhausted cooldown
		if err := s.RecordFailure(ctx, "itm_c", "tv-parser", "exhausted", "boom", 3, nextElig); err != nil {
			t.Fatalf("RecordFailure: %v", err)
		}
		rows, err := s.ListFailures(ctx)
		if err != nil || len(rows) != 1 {
			t.Fatalf("ListFailures = %d rows, err %v, want 1", len(rows), err)
		}
		r := rows[0]
		if !r.NextEligibleAt.After(now) {
			t.Fatalf("NextEligibleAt %v not After now %v (should be WITHIN cooldown)", r.NextEligibleAt, now)
		}
		ceiling := now.Add(8 * 24 * time.Hour)
		if !r.NextEligibleAt.Before(ceiling) {
			t.Fatalf("NextEligibleAt %v not Before 8d ceiling %v", r.NextEligibleAt, ceiling)
		}
	})
}
